// Writes lib/content-manifest.ts: static imports of every JSON file in
// content/experiments, content/misconceptions, content/hints and
// content/theory, so adding an experiment is just adding its JSON file.
// Runs before dev, build and test (see package.json).
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const kinds = ["experiments", "misconceptions", "hints", "theory"];

const lines = [
  "// Generated by scripts/content-manifest.mjs. Do not edit by hand.",
];
const exportsByKind = {};

for (const kind of kinds) {
  const dir = join(root, "content", kind);
  let files = [];
  try {
    files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
  } catch {
    files = [];
  }
  exportsByKind[kind] = files.map((file, i) => {
    const name = `${kind}_${i}`;
    lines.push(`import ${name} from "@/content/${kind}/${file}";`);
    return name;
  });
}

lines.push("");
for (const kind of kinds) {
  lines.push(`export const ${kind}: unknown[] = [${exportsByKind[kind].join(", ")}];`);
}

writeFileSync(join(root, "lib", "content-manifest.ts"), lines.join("\n") + "\n");
console.log(
  "content manifest:",
  kinds.map((k) => `${exportsByKind[k].length} ${k}`).join(", "),
);
